    s = requests.session()
    s.get(httpbin('cookies/set?foo=bar'))
    assert s.cookies['foo'] == 'bar'
    s.get(
        httpbin('response-headers'),
        params={
            'Set-Cookie':
                'foo=deleted; expires=Thu, 01-Jan-1970 00:00:01 GMT'
        }
    )
    assert 'foo' not in s.cookies

